@@ -0,0 +1,68 @@
+export function checkMetadata(metadata, schema) {
+  const missing = [];
+  const invalid = [];
+
+  for (const field of Object.keys(schema)) {
+    const rule = schema[field];
+    const value = metadata[field];
+
+    // Check if field is missing (absent or null/undefined)
+    if (value === undefined || value === null) {
+      if (rule.required === true) {
+        missing.push(field);
+      }
+      continue;
+    }
+
+    // Type check
+    const expectedType = rule.type;
+    let typeValid = true;
+    if (expectedType === 'string' && typeof value !== 'string') {
+      typeValid = false;
+    } else if (expectedType === 'number' && (typeof value !== 'number' || isNaN(value))) {
+      typeValid = false;
+    } else if (expectedType === 'boolean' && typeof value !== 'boolean') {
+      typeValid = false;
+    } else if (expectedType === 'array' && !Array.isArray(value)) {
+      typeValid = false;
+    } else if (expectedType === 'object' && (typeof value !== 'object' || value === null)) {
+      typeValid = false;
+    }
+
+    if (!typeValid) {
+      invalid.push({ field, reason: `Expected type ${expectedType}, got ${typeof value}` });
+      continue;
+    }
+
+    // Length checks for strings and arrays
+    if (expectedType === 'string') {
+      if (rule.minLength !== undefined && value.length < rule.minLength) {
+        invalid.push({ field, reason: `String length ${value.length} is less than minLength ${rule.minLength}` });
+      }
+      if (rule.maxLength !== undefined && value.length > rule.maxLength) {
+        invalid.push({ field, reason: `String length ${value.length} exceeds maxLength ${rule.maxLength}` });
+      }
+    } else if (expectedType === 'array') {
+      if (rule.minLength !== undefined && value.length < rule.minLength) {
+        invalid.push({ field, reason: `Array length ${value.length} is less than minLength ${rule.minLength}` });
+      }
+      if (rule.maxLength !== undefined && value.length > rule.maxLength) {
+        invalid.push({ field, reason: `Array length ${value.length} exceeds maxLength ${rule.maxLength}` });
+      }
+    }
+
+    // Pattern check for strings
+    if (expectedType === 'string' && rule.pattern !== undefined) {
+      const regex = new RegExp(rule.pattern);
+      if (!regex.test(value)) {
+        invalid.push({ field, reason: `Value does not match pattern ${rule.pattern}` });
+      }
+    }
+  }
+
+  return Object.freeze({
+    valid: missing.length === 0 && invalid.length === 0,
+    missing: Object.freeze(missing),
+    invalid: Object.freeze(invalid)
+  });
+}

